function rand(n){return Math.floor(Math.random()*n)}
function teamId(tier,index){return `t${tier}-${index}`}
function allTeams(){return LEAGUES.flatMap((l,tier)=>l.teams.map((x,index)=>({id:teamId(tier,index),name:x[0],city:x[1],strength:x[2],badge:x[3],tier,league:l.name}))) }
const TEAMS=allTeams();
function roster(team){return Array.from({length:18},(_,i)=>({id:`${team.id}-p${i}`,name:`${FIRST[(team.strength+i*3)%FIRST.length]} ${LAST[(team.strength*2+i*5)%LAST.length]}`,pos:POS[i],age:18+((team.strength+i*7)%17),ovr:Math.max(42,Math.round(team.strength-9+Math.random()*18-(i>13?5:0))),value:Math.round((team.strength-35)*(.06+Math.random()*.14)),fitness:88+rand(13),morale:66+rand(30),starter:i<11}))}
function makeRounds(teams){let arr=teams.map(t=>t.id), rounds=[];for(let r=0;r<arr.length-1;r++){let games=[];for(let i=0;i<arr.length/2;i++){let a=arr[i],b=arr[arr.length-1-i];games.push({home:r%2?b:a,away:r%2?a:b,played:false,score:null})}rounds.push(games);arr=[arr[0],arr[arr.length-1],...arr.slice(1,-1)]}let second=rounds.map(g=>g.map(m=>({home:m.away,away:m.home,played:false,score:null})));return [...rounds,...second]}
function freshState(teamId0){let selected=TEAMS.find(t=>t.id===teamId0), squads={},leagues={};TEAMS.forEach(t=>squads[t.id]=roster(t));LEAGUES.forEach((l,i)=>{const teams=TEAMS.filter(t=>t.tier===i);leagues[i]={round:0,rounds:makeRounds(teams),table:Object.fromEntries(teams.map(t=>[t.id,{pts:0,p:0,w:0,d:0,l:0,gf:0,ga:0}]))}});return{clubId:selected.id,manager:'Alex Ben-Ami',season:2025,week:1,page:'dashboard',tactics:{formation:'4-3-3',style:'Balanced',press:'Standard'},squads,leagues,transferPool:makeTransferPool(selected),news:[{title:`You have been appointed manager of ${selected.name}.`,time:'Today'}],played:0}}
function makeTransferPool(team){return Array.from({length:12},(_,i)=>({id:`free-${team.id}-${i}`,name:`${FIRST[rand(FIRST.length)]} ${LAST[rand(LAST.length)]}`,pos:POS[rand(POS.length)],age:19+rand(12),ovr:Math.max(43,team.strength-9+rand(13)),value:Math.max(1,Math.round((team.strength-40)*(.05+Math.random()*.18))),free:true}))}
