function save(){try{localStorage.setItem('touchline-save',JSON.stringify(state))}catch(e){}}
function load(){try{state=JSON.parse(localStorage.getItem('touchline-save'))}catch(e){} if(state&&!TEAMS.some(t=>t.id===state.clubId))state=null}
function userTeam(){return TEAMS.find(t=>t.id===state.clubId)}
function myLeague(){return state.leagues[userTeam().tier]}
function teamName(id){return TEAMS.find(t=>t.id===id)?.name||'Unknown'}
function teamObj(id){return TEAMS.find(t=>t.id===id)}
function myPlayers(){return state.squads[state.clubId]}
function sortedTeams(tier){let data=state.leagues[tier].table;return TEAMS.filter(t=>t.tier===tier).sort((a,b)=>{let x=data[a.id],y=data[b.id];return y.pts-x.pts||(y.gf-y.ga)-(x.gf-x.ga)||y.gf-x.gf||a.name.localeCompare(b.name)})}
function myPosition(){return sortedTeams(userTeam().tier).findIndex(t=>t.id===state.clubId)+1}
function render(){if(!state){renderSetup();return}let root=$('#app');root.innerHTML=`<div class="shell"><aside class="sidebar" id="sidebar">${sidebar()}</aside><main class="main"><header class="topbar"><div class="top-left"><button class="mobile-menu" id="menuToggle">☰</button><div><div class="eyebrow">${esc(userTeam().league)} · ${state.season}/${state.season+1}</div><div class="top-title">${esc(userTeam().name)}</div></div></div><div class="top-right"><div class="date-pill">${dateLabel()}</div><button class="btn" id="advanceBtn">${myLeague().round>=30?'Season review':'Advance week'} <span>→</span></button></div></header><div class="content">${pageContent()}</div></main></div>`;bind();}
