function upcoming(){let league=myLeague(),matches=league.rounds[league.round]||[],m=matches.find(x=>x.home===state.clubId||x.away===state.clubId);return m?{...m,opp:teamObj(m.home===state.clubId?m.away:m.home),home:m.home===state.clubId}:null}
function nextMatchCard(){let m=upcoming(),pos=myPosition();if(!m)return `<section class="hero"><div class="eyebrow">SEASON COMPLETE</div><h2>Full time on the season.</h2><p class="hero-sub">The campaign is in the books. Take a look at your final position.</p><button class="btn" data-action="season">Start next season →</button></section>`;return `<section class="hero"><div class="eyebrow">NEXT MATCH · ${userTeam().league.toUpperCase()} · ROUND ${myLeague().round+1}</div><h2>${m.home?'Home':'Away'} day is coming.</h2><div class="hero-sub">A big three points are up for grabs. You’re currently ${ordinal(pos)} in the table.</div><div class="matchup"><div class="match-team home">${badge(userTeam())}<div>${esc(userTeam().name)}<div class="match-info">${m.home?'Home':'Away'} · ${Math.round(teamRating(userTeam()))} OVR</div></div></div><div class="versus">VS</div><div class="match-team">${badge(m.opp)}<div>${esc(m.opp.name)}<div class="match-info">${m.home?'Away':'Home'} · ${m.opp.strength} OVR</div></div></div></div><div class="hero-actions"><button class="btn" id="playMatch">Play match&nbsp; →</button><span class="hint">Your tactics are set to ${state.tactics.formation} · ${state.tactics.style}</span></div></section>`}
function ordinal(n){return n===1?'1st':n===2?'2nd':n===3?'3rd':`${n}th`}
function tableRows(tier,limit=8){let sorted=sortedTeams(tier),data=state.leagues[tier].table;return sorted.slice(0,limit).map((t,i)=>{let r=data[t.id];return `<tr class="${t.id===state.clubId?'user-row':''}" data-table-team="${t.id}"><td class="pos">${i+1}</td><td><div class="team-cell"><span class="tiny-crest">${t.badge}</span>${esc(t.name)}</div></td><td>${r.p}</td><td>${r.w}-${r.d}-${r.l}</td><td>${r.gf-r.ga}</td><td class="points">${r.pts}</td></tr>`}).join('')}
function dashboard(){let sorted=sortedTeams(userTeam().tier),rank=myPosition(),n=myPlayers().filter(p=>p.starter).slice(0,4);return `<div class="page-head"><div><div class="eyebrow">MANAGER OVERVIEW</div><h1>Good ${new Date().getHours()<12?'morning':'afternoon'}, Alex.</h1><p>Here’s the latest from your corner of Israeli football.</p></div><button class="btn secondary small" data-page="tactics">Set up team ↗</button></div><div class="grid-dash"><div>${nextMatchCard()}<div class="metrics"><div class="metric"><label>LEAGUE POSITION</label><strong>${ordinal(rank)} <small>of 16</small></strong><small class="good">${rank<=2?'▲ Promotion places':rank>=15?'▼ Relegation zone':'● Mid-table'}</small></div><div class="metric"><label>POINTS</label><strong>${myLeague().table[state.clubId].pts}</strong><small>${myLeague().table[state.clubId].w} wins this season</small></div><div class="metric"><label>CLUB BALANCE</label><strong>₪${clubBalance().toLocaleString()}k</strong><small class="good">+₪${incomePerWeek()}k weekly</small></div><div class="metric"><label>SQUAD STRENGTH</label><strong>${Math.round(teamRating(userTeam()))}</strong><small>First team average</small></div></div><section class="panel"><div class="panel-head"><div class="panel-title">${userTeam().league} · standings</div><button class="text-btn" data-page="table">Full table →</button></div><div class="table-wrap"><table class="league-table"><thead><tr><th>#</th><th>CLUB</th><th>P</th><th>W-D-L</th><th>GD</th><th>PTS</th></tr></thead><tbody>${tableRows(userTeam().tier,6)}</tbody></table></div></section></div><div class="right-stack"><section class="panel"><div class="panel-head"><div class="panel-title">Key players</div><button class="text-btn" data-page="squad">Squad →</button></div><div class="squad-list">${n.map(p=>`<div class="player-row"><div class="player-num">${p.pos}</div><div class="player-info"><b>${esc(p.name)}</b><small>${p.age} yrs · ${p.pos==='ST'?'Forward':p.pos==='GK'?'Goalkeeper':'First team'}</small></div><div class="rating">${p.ovr}</div></div>`).join('')}</div></section><section class="panel"><div class="panel-head"><div class="panel-title">Around the club</div><span class="eyebrow">LATEST</span></div>${state.news.slice(0,4).map(n=>`<div class="news-item"><span class="news-dot"></span><div><b>${esc(n.title)}</b><small>${n.time}</small></div></div>`).join('')}</section><section class="panel"><div class="panel-head"><div class="panel-title">Season objective</div><span class="tag green">BOARD</span></div><div style="padding:15px 17px;color:#aab8ac;font-size:11px;line-height:1.6">${userTeam().tier===0?'Finish in the top half and make the supporters proud.':`Push for promotion to ${LEAGUES[userTeam().tier-1]?.name||'the next division'}.`}<br><b style="color:var(--lime)">Your target: top 2</b></div></section></div></div>`}
function squadPage(){let players=myPlayers(),filter=$('#squadFilter')?.value||'All positions';let shown=filter==='All positions'?players:players.filter(p=>p.pos===filter);return `<div class="page-head"><div><div class="eyebrow">FIRST TEAM · ${players.length} PLAYERS</div><h1>The squad</h1><p>Manage your matchday squad, check player form and build your starting XI.</p></div><div class="filter-row"><select id="squadFilter"><option ${filter==='All positions'?'selected':''}>All positions</option>${['GK','DEF','MID','ATT'].map(x=>`<option ${filter===x?'selected':''}>${x}</option>`).join('')}</select><button class="btn secondary small" data-action="autoLineup">Auto pick XI</button></div></div><section class="panel"><div class="table-wrap"><table class="league-table squad-table"><thead><tr><th>PLAYER</th><th>POS</th><th>AGE</th><th>OVR</th><th>FITNESS</th><th>MORALE</th><th>STATUS</th><th></th></tr></thead><tbody>${shown.map(p=>`<tr><td class="player-name">${esc(p.name)}</td><td><span class="tag">${p.pos}</span></td><td>${p.age}</td><td class="player-ovr">${p.ovr}</td><td>${p.fitness}%</td><td>${p.morale}%</td><td><span class="status">${p.starter?'● Starting XI':'On bench'}</span></td><td><button class="icon-btn" data-player="${p.id}">${p.starter?'Bench':'Start'}</button></td></tr>`).join('')}</tbody></table></div></section><div style="display:flex;justify-content:space-between;color:var(--muted);font-size:10px;padding:12px 3px"><span>Starting XI: ${players.filter(p=>p.starter).length} / 11</span><span>Average rating: ${Math.round(teamRating(userTeam()))}</span></div>`}
function classify(p){return ['GK'].includes(p.pos)?'GK':['CB','RB','LB'].includes(p.pos)?'DEF':['DM','CM','AM'].includes(p.pos)?'MID':'ATT'}
function tacticsPage(){let players=myPlayers().filter(p=>p.starter);let groups={GK:players.filter(p=>classify(p)==='GK'),DEF:players.filter(p=>classify(p)==='DEF'),MID:players.filter(p=>classify(p)==='MID'),ATT:players.filter(p=>classify(p)==='ATT')};return `<div class="page-head"><div><div class="eyebrow">MATCH PREPARATION</div><h1>Team tactics</h1><p>Shape, style and intensity — make your game plan.</p></div><span class="tag green">${Math.round(teamRating(userTeam()))} SQUAD OVR</span></div><div class="page-grid"><section class="panel"><div class="panel-head"><div class="panel-title">Starting formation · ${state.tactics.formation}</div><span class="eyebrow">MATCHDAY XI</span></div><div style="padding:15px"><div class="formation-board"><div class="pitch-lines"></div>${['ATT','MID','DEF','GK'].map(g=>`<div class="formation-row">${(groups[g].length?groups[g]:[{name:'Select player',pos:'+'}]).map(p=>`<div class="pitch-player"><div class="pitch-shirt">${p.pos==='GK'?'GK':'●'}</div><b>${esc(p.name.split(' ')[0])}</b><small>${p.ovr||'—'} OVR</small></div>`).join('')}</div>`).join('')}</div></div></section><aside class="panel"><div class="panel-head"><div class="panel-title">Game plan</div></div><div class="tactic-card"><label>FORMATION</label><div class="option-group">${Object.keys(FORMATIONS).map(f=>`<button class="option ${state.tactics.formation===f?'active':''}" data-tactic="formation" data-value="${f}">${f}</button>`).join('')}</div></div><div class="tactic-card"><label>PLAYING STYLE</label><div class="option-group">${['Balanced','Possession','Counter','Attacking'].map(f=>`<button class="option ${state.tactics.style===f?'active':''}" data-tactic="style" data-value="${f}">${f}</button>`).join('')}</div></div><div class="tactic-card"><label>PRESSING INTENSITY</label><div class="option-group">${['Low','Standard','High'].map(f=>`<button class="option ${state.tactics.press===f?'active':''}" data-tactic="press" data-value="${f}">${f}</button>`).join('')}</div></div><div style="padding:13px 15px;color:var(--muted);font-size:10px;line-height:1.55">Tactics affect your team's performance in every match. High pressing boosts chances but drains fitness.</div></aside></div>`}

