function tablePage(){let tier=Number($('#leagueFilter')?.value??userTeam().tier),current=sortedTeams(tier),stand=state.leagues[tier].table;return `<div class="page-head"><div><div class="eyebrow">THE PYRAMID · 64 CLUBS</div><h1>League table</h1><p>Four tiers. One dream. Every point matters.</p></div><div class="filter-row"><select id="leagueFilter">${LEAGUES.map((l,i)=>`<option value="${i}" ${tier===i?'selected':''}>${l.name}</option>`).join('')}</select></div></div><section class="panel"><div class="panel-head"><div class="panel-title">${LEAGUES[tier].name} · ${state.season}/${state.season+1}</div><span class="eyebrow">ROUND ${state.leagues[tier].round} / 30</span></div><div class="table-wrap"><table class="league-table"><thead><tr><th>#</th><th>CLUB</th><th>P</th><th>W</th><th>D</th><th>L</th><th>GF</th><th>GA</th><th>GD</th><th>PTS</th></tr></thead><tbody>${current.map((t,i)=>{let r=stand[t.id];return `<tr class="${t.id===state.clubId?'user-row':''}"><td class="pos">${i<2?'▲':i>13?'▼':i+1}</td><td><div class="team-cell"><span class="tiny-crest">${t.badge}</span>${esc(t.name)}${t.id===state.clubId?' <span class="tag green">YOU</span>':''}</div></td><td>${r.p}</td><td>${r.w}</td><td>${r.d}</td><td>${r.l}</td><td>${r.gf}</td><td>${r.ga}</td><td>${r.gf-r.ga}</td><td class="points">${r.pts}</td></tr>`}).join('')}</tbody></table></div><div style="padding:12px 16px;color:var(--muted);font-size:10px">▲ Promotion places &nbsp;&nbsp; ▼ Relegation places</div></section><div class="page-grid" style="margin-top:16px"><section class="panel"><div class="panel-head"><div class="panel-title">How promotion works</div></div><div style="padding:16px;color:var(--muted);font-size:11px;line-height:1.7">Top two clubs move up a division at the end of the season. Bottom two drop down. The champion earns bragging rights — and a stronger transfer budget next year.</div></section><section class="panel"><div class="panel-head"><div class="panel-title">Division ladder</div></div>${LEAGUES.map((l,i)=>`<div class="news-item"><span class="news-dot" style="background:${i===userTeam().tier?'var(--lime)':'#536357'}"></span><div><b>${l.name}</b><small>${i===0?'Top flight':i===3?'Fourth tier':'Division '+(i+1)} · 16 clubs ${i===userTeam().tier?' · YOUR CLUB':''}</small></div></div>`).join('')}</section></div>`}
function fixturesPage(){let tier=Number($('#fixtureFilter')?.value??userTeam().tier),league=state.leagues[tier];return `<div class="page-head"><div><div class="eyebrow">MATCH CENTRE</div><h1>Fixtures & results</h1><p>Every match across the Israeli football pyramid.</p></div><div class="filter-row"><select id="fixtureFilter">${LEAGUES.map((l,i)=>`<option value="${i}" ${tier===i?'selected':''}>${l.name}</option>`).join('')}</select></div></div>${league.rounds.map((matches,i)=>`<section class="panel" style="margin-bottom:13px"><div class="panel-head"><div class="panel-title">Round ${i+1}</div><span class="eyebrow">${i<league.round?'COMPLETED':i===league.round?'UP NEXT':'UPCOMING'}</span></div>${matches.map(m=>`<div class="fixture-row"><div class="fixture-date">${m.played?'FULL TIME':i===league.round?'THIS WEEK':'TBC'}</div><div class="fixture-teams"><span>${esc(teamName(m.home))}</span><span class="dim">vs</span><span>${esc(teamName(m.away))}</span></div><div class="score">${m.played?`${m.score[0]} – ${m.score[1]}`:'—'}</div><div class="fixture-status">${m.home===state.clubId||m.away===state.clubId?'<span class="tag green">YOUR MATCH</span>':''}</div></div>`).join('')}</section>`).join('')}`}
function transfersPage(){let pool=state.transferPool;return `<div class="page-head"><div><div class="eyebrow">SQUAD BUILDING</div><h1>Transfer market</h1><p>Free agents looking for their next opportunity.</p></div><span class="tag green">AVAILABLE BUDGET · ₪${clubBalance()}k</span></div><div class="page-grid"><section class="panel"><div class="panel-head"><div class="panel-title">Available players</div><span class="eyebrow">${pool.length} PLAYERS</span></div>${pool.length?pool.map(p=>`<div class="transfer-card"><div class="player-num">${p.pos}</div><div class="player-info"><b>${esc(p.name)}</b><small>${p.age} yrs · ${p.pos} · OVR ${p.ovr}</small></div><div class="player-cost">₪${p.value}k<small>signing fee</small></div><button class="btn small" data-sign="${p.id}">Sign</button></div>`).join(''):'<div class="empty">No free agents available right now.</div>'}</section><aside class="panel"><div class="panel-head"><div class="panel-title">Your finances</div></div><div class="tactic-card"><label>CLUB BALANCE</label><b style="font:700 23px var(--display);color:var(--lime)">₪${clubBalance()}k</b></div><div class="tactic-card"><label>WEEKLY WAGE BUDGET</label><b>₪${incomePerWeek()}k</b><div style="color:var(--muted);font-size:10px;margin-top:5px">Available for new signings</div></div><div style="padding:13px 15px;color:var(--muted);font-size:10px;line-height:1.6">Players join your squad immediately. A stronger squad raises your match rating and improves your chances of promotion.</div></aside></div>`}
function clubBalance(){return Math.max(0,120+(4-userTeam().tier)*55-state.played*2)}function incomePerWeek(){return Math.max(1,8-userTeam().tier)}
function teamRating(team){let ps=state.squads[team.id]||[];if(!ps.length)return team.strength;let starters=ps.filter(p=>p.starter);return starters.length?starters.reduce((s,p)=>s+p.ovr*(p.fitness/100),0)/starters.length:ps.reduce((s,p)=>s+p.ovr,0)/ps.length}
EOF

