function poisson(lambda){let l=Math.exp(-Math.max(.15,Math.min(3.8,lambda))),k=0,p=1;do{k++;p*=Math.random()}while(p>l&&k<8);return k-1}
function simulateGame(m,tier){let home=teamObj(m.home),away=teamObj(m.away),h=teamRating(home),a=teamRating(away);if(m.home===state.clubId||m.away===state.clubId){let style=state.tactics.style,press=state.tactics.press;let bonus=style==='Attacking'?3:style==='Possession'?2:style==='Counter'?1:0;let energy=press==='High'?-2:press==='Low'?-1:0;if(m.home===state.clubId)h+=bonus+energy;else a+=bonus+energy}let hg=poisson(1.28+(h-a)/22+.16),ag=poisson(1.08+(a-h)/23);m.played=true;m.score=[hg,ag];let table=state.leagues[tier].table;[[m.home,hg,ag],[m.away,ag,hg]].forEach(([id,gf,ga])=>{let r=table[id];r.p++;r.gf+=gf;r.ga+=ga;if(gf>ga){r.w++;r.pts+=3}else if(gf===ga){r.d++;r.pts++}else r.l++});return m.score}
function advanceWeek(showMatch=true){let userTier=userTeam().tier,week=state.leagues[userTier].round;if(week>=30){toast('The season has ended. Review your campaign.');return}let userResult=null,results=[];for(let tier=0;tier<4;tier++){let lg=state.leagues[tier],games=lg.rounds[lg.round]||[];games.forEach(m=>{let score=simulateGame(m,tier);if(m.home===state.clubId||m.away===state.clubId)userResult={home:m.home===state.clubId,opp:teamObj(m.home===state.clubId?m.away:m.home),score,round:week+1}});lg.round++}state.played++;myPlayers().forEach(p=>{p.fitness=Math.max(54,Math.min(100,p.fitness-(state.tactics.press==='High'?13:state.tactics.press==='Low'?5:9)+rand(10)));p.morale=Math.max(35,Math.min(99,p.morale+rand(13)-3))});if(userResult){let us=userResult.home?userResult.score[0]:userResult.score[1],them=userResult.home?userResult.score[1]:userResult.score[0],result=us>them?'Victory':us===them?'A draw':'Defeat';let headline=`${result}: ${userTeam().name} ${userResult.score[0]}–${userResult.score[1]} ${userResult.opp.name}`;state.news.unshift({title:headline,time:`Round ${userResult.round}`});state.news=state.news.slice(0,8);save();render();if(showMatch)showMatchModal(userResult,result);else toast(headline)}else{save();render()} }
function showMatchModal(r,result){let us=r.home?r.score[0]:r.score[1],them=r.home?r.score[1]:r.score[0],tone=us>them?'var(--lime)':us===them?'var(--orange)':'var(--red)';let backdrop=document.createElement('div');backdrop.className='modal-backdrop';backdrop.innerHTML=`<div class="modal" style="text-align:center"><div class="eyebrow">FULL TIME · ROUND ${r.round}</div><h2 style="color:${tone}">${result}</h2><p>${esc(userTeam().league)} · ${r.home?'Home':'Away'}</p><div style="display:flex;align-items:center;justify-content:center;gap:22px;margin:27px 0"><div>${badge(r.home?userTeam():r.opp)}<b style="display:block;font-size:12px;margin-top:8px">${esc(r.home?userTeam().name:r.opp.name)}</b></div><strong style="font:700 33px var(--display)">${r.score[0]} – ${r.score[1]}</strong><div>${badge(r.home?r.opp:userTeam())}<b style="display:block;font-size:12px;margin-top:8px">${esc(r.home?r.opp.name:userTeam().name)}</b></div></div><p>${us>them?'A statement performance. The supporters will be delighted.':us===them?'A hard-fought point — there’s plenty to build on.':'A disappointing result, but there’s time to turn things around.'}</p><button class="btn" id="modalClose">Continue season →</button></div>`;document.body.appendChild(backdrop);backdrop.addEventListener('click',e=>{if(e.target===backdrop||e.target.id==='modalClose')backdrop.remove()})}
function autoLineup(){let p=myPlayers().slice().sort((a,b)=>b.ovr-a.ovr);p.forEach((x,i)=>x.starter=i<11);save();render();toast('Your strongest XI has been selected.')}
function setStarted(id){let list=myPlayers(),p=list.find(x=>x.id===id);if(!p)return;if(p.starter){p.starter=false}else{let current=list.filter(x=>x.starter);if(current.length>=11){let weakest=current.sort((a,b)=>a.ovr-b.ovr)[0];weakest.starter=false}p.starter=true}save();render()}
function signPlayer(id){let p=state.transferPool.find(x=>x.id===id);if(!p)return;if(clubBalance()<p.value){toast('Not enough funds for this signing.');return}let newP={...p,id:`${state.clubId}-${Date.now()}`,fitness:95,morale:80,starter:false};delete newP.free;state.squads[state.clubId].push(newP);state.transferPool=state.transferPool.filter(x=>x.id!==id);state.news.unshift({title:`${p.name} signed for ${userTeam().name}.`,time:'Transfer update'});save();render();toast(`${p.name} has joined the squad.`)}
function startSeason(){let oldTier=userTeam().tier,moves=[];for(let tier=0;tier<3;tier++){let ups=sortedTeams(tier+1).slice(0,2),downs=sortedTeams(tier).slice(-2);for(let i=0;i<2;i++)moves.push([ups[i].id,downs[i].id])}moves.forEach(([up,down])=>{let a=teamObj(up),b=teamObj(down),t=a.tier;a.tier=b.tier;b.tier=t;a.league=LEAGUES[a.tier].name;b.league=LEAGUES[b.tier].name});state.season++;state.played=0;state.leagues={};LEAGUES.forEach((l,i)=>{let teams=TEAMS.filter(t=>t.tier===i);state.leagues[i]={round:0,rounds:makeRounds(teams),table:Object.fromEntries(teams.map(t=>[t.id,{pts:0,p:0,w:0,d:0,l:0,gf:0,ga:0}]))}});state.transferPool=makeTransferPool(userTeam());state.news.unshift({title:`Season ${state.season}/${state.season+1} is underway.`,time:'Season start'});state.page='dashboard';save();render();toast(`Welcome to season ${state.season}/${state.season+1}!`)}
function renderSetup(){let root=$('#app');root.innerHTML=`<div class="modal-backdrop"><div class="modal"><div class="brand" style="padding:0 0 15px"><div class="brand-mark">T</div><div class="brand-name">touchline<span>.</span></div></div><div class="eyebrow">YOUR STORY STARTS HERE · ISRAEL</div><h2>Take the hot seat.</h2><p>Choose your club and lead them through the Israeli football pyramid. Four divisions, 64 clubs, and promotion glory — your career begins now.</p><div class="league-pick">${LEAGUES.map((l,i)=>`<button class="${setupTier===i?'active':''}" data-set-tier="${i}"><b>DIV ${i+1}</b><br>${l.name}</button>`).join('')}</div><div class="club-grid">${TEAMS.filter(t=>t.tier===setupTier).map(t=>`<button class="club-choice ${setupChoice===t.id?'selected':''}" data-club="${t.id}"><b>${t.badge} &nbsp;${esc(t.name)}</b><small>${esc(t.city)} · ${t.strength} OVR</small></button>`).join('')}</div><div class="modal-footer"><small>Progress saves automatically on this device.</small><button class="btn" id="startCareer" ${setupChoice?'':'disabled'} style="${setupChoice?'':'opacity:.45;cursor:not-allowed'}">Start career →</button></div></div></div>`;root.querySelectorAll('[data-set-tier]').forEach(b=>b.onclick=()=>{setupTier=+b.dataset.setTier;setupChoice=null;renderSetup()});root.querySelectorAll('[data-club]').forEach(b=>b.onclick=()=>{setupChoice=b.dataset.club;renderSetup()});$('#startCareer').onclick=()=>{if(!setupChoice)return;state=freshState(setupChoice);save();render()}}
function toast(msg){document.querySelector('.notification')?.remove();let n=document.createElement('div');n.className='notification';n.textContent=msg;document.body.appendChild(n);setTimeout(()=>n.remove(),2600)}
